def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_c = sum(1 for a in my if a == 'C')
    my_d = n - my_c
    op_c = sum(1 for a in op if a == 'C')
    op_d = n - op_c

    last_my = my[-1]
    last_op = op[-1]

    # Endgame: defect if opponent likely cooperates
    remaining = 100 - n
    if remaining <= 3:
        if op_c * 2 >= n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Opponent heavily defect-prone
    if op_d * 3 >= n * 2:
        return 'D' if last_op == 'D' or rng.random() < 0.8 else 'C'

    # Opponent just defected
    if last_op == 'D':
        recent_op = op[-6:] if n >= 6 else op
        recent_d = sum(1 for a in recent_op if a == 'D')
        if recent_d >= 3:
            return 'D'
        # Forgive if opponent has had a long cooperative run
        if op_c >= n - 1:
            return 'C'
        if last_my == 'D' and recent_d <= 1 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent just cooperated
    if op_d == 0:
        # Pure cooperator: exploit occasionally late
        if n >= 10 and rng.random() < 0.12:
            return 'D'
        return 'C'
    if op_d * 3 <= n:
        # Mostly cooperative: exploit a bit
        if n >= 5 and rng.random() < 0.08:
            return 'D'
        return 'C'
    # Mixed opponent
    recent_op = op[-5:] if n >= 5 else op
    recent_d = sum(1 for a in recent_op if a == 'D')
    if recent_d >= 2:
        if rng.random() < 0.5:
            return 'D'
    return 'C'
